import { useEffect, useState } from "react";

export default function AdminOrders() {
  const [orders, setOrders] = useState([]);

  const fetchOrders = async () => {
    try {
      const res = await fetch("http://127.0.0.1:8000/api/orders/");
      const data = await res.json();
      setOrders(data);
    } catch (err) {
      console.error("Admin orders fetch failed");
    }
  };

  useEffect(() => {
    fetchOrders();

    // ✅ LIVE SYNC (every 3 seconds)
    const interval = setInterval(fetchOrders, 3000);
    return () => clearInterval(interval);
  }, []);

  const updateStatus = async (order_id, status) => {
    await fetch("http://127.0.0.1:8000/api/orders/update-status/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ order_id, status }),
    });

    // ✅ REFRESH AFTER UPDATE
    fetchOrders();
  };

  return (
    <div>
      <h3>Admin Orders</h3>

      {orders.map(order => (
        <div key={order.order_id} className="order-card">
          <p>
            <b>#{order.order_id}</b> | {order.user}
          </p>
          <p>Status: {order.status}</p>

          <button onClick={() => updateStatus(order.order_id, "Preparing")}>
            Preparing
          </button>

          <button onClick={() => updateStatus(order.order_id, "Completed")}>
            Completed
          </button>
        </div>
      ))}
    </div>
  );
}
